#!/usr/bin/env node
// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
import fs from 'node:fs';
import { applyPatch, PatchError } from './jsonpatch.mjs';

const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
const MAX_BYTES = 1048576;
const MAX_DEPTH = 1000;
const CHUNK = 65536;

class CliError extends Error {
  constructor(message, code) {
    super(message);
    this.code = code;
  }
}

function sleep(ms) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

// Reads at most MAX_BYTES + 1 bytes from fd; returns a Buffer or throws an fs error.
function readFd(fd) {
  const chunks = [];
  let total = 0;
  for (;;) {
    const buf = Buffer.alloc(CHUNK);
    let n;
    try {
      n = fs.readSync(fd, buf, 0, CHUNK, null);
    } catch (err) {
      if (err.code === 'EAGAIN') {
        sleep(10);
        continue;
      }
      throw err;
    }
    if (n === 0) break;
    chunks.push(buf.subarray(0, n));
    total += n;
    if (total > MAX_BYTES) break;
  }
  return Buffer.concat(chunks, total);
}

function readFailure(name, err) {
  const reason = err?.code === 'EISDIR' ? 'is a directory' : 'cannot read';
  return new CliError(`Error: ${name}: ${reason}`, 1);
}

function isDirectory(path) {
  try {
    return fs.statSync(path).isDirectory();
  } catch {
    return false;
  }
}

function readInput(arg) {
  if (arg === '-') {
    try {
      return readFd(0);
    } catch {
      throw new CliError('Error: stdin: cannot read', 1);
    }
  }
  let fd;
  try {
    fd = fs.openSync(arg, 'r');
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
      throw new CliError(`Error: ${arg}: no such file`, 1);
    }
    if (err.code === 'EISDIR' || isDirectory(arg)) throw new CliError(`Error: ${arg}: is a directory`, 1);
    throw readFailure(arg, err);
  }
  try {
    if (fs.fstatSync(fd).isDirectory()) throw new CliError(`Error: ${arg}: is a directory`, 1);
    return readFd(fd);
  } catch (err) {
    if (err instanceof CliError) throw err;
    throw readFailure(arg, err);
  } finally {
    fs.closeSync(fd);
  }
}

// Depth of a parsed JSON value, computed without recursion.
function depthOf(value) {
  let max = 0;
  const stack = [[value, 0]];
  while (stack.length) {
    const [v, d] = stack.pop();
    if (v === null || typeof v !== 'object') continue;
